{
  "findings": [
    {
      "cwe": "CWE-22",
      "class": "Expand",
      "method": "extractFile",
      "explanation": "The entryName from the ZIP entry is passed to FileUtils.resolveFile without any validation to ensure the resulting path is within the destination directory. A malicious ZIP file with entries containing path traversal sequences (e.g., '../') could cause files to be extracted to arbitrary locations outside the intended directory, leading to overwriting sensitive files or remote code execution."
    },
    {
      "cwe": "CWE-409",
      "class": "Expand",
      "method": "extractFile",
      "explanation": "The method reads from the ZIP entry and writes to a file without any limit on the total number of bytes or the compression ratio. A malicious ZIP bomb (a small archive that expands to an enormous size) could exhaust disk space or cause denial of service by consuming excessive resources."
    }
  ]
}

